  static readonly int[] MouseCalibrationPresetIds={255,28,27,26,24,23,25,20,21,22,18,19,12,13,11,10,7,8,14,0,1,15,16,17};
  static bool MouseCalibrationDirty(MouseCalibrationDraft d){return d!=null&&(d.DirtyMode||d.DirtyPreset||d.DirtyLod||d.DirtyGlass);}
  static bool MouseCalibrationDraftValid(MouseCalibrationDraft d){
   if(d==null||d.DeviceId==null||d.DeviceId.Length>64||d.DeviceId.Length>0&&!MouseZoneUiFacts.Identity(d.DeviceId,7546)&&!MouseZoneUiFacts.Identity(d.DeviceId,7548)||d.CapturedAt!=null&&!MouseZoneUiFacts.Timestamp(d.CapturedAt))return false;
   if(d.Mode.HasValue&&d.Mode!=0&&d.Mode!=255||d.Material.HasValue&&(d.Material<0||d.Material>28&&d.Material!=255)||d.LodMode.HasValue&&(d.LodMode<0||d.LodMode>2)||d.NormalLod.HasValue&&(d.NormalLod<0||d.NormalLod>2)||new[]{d.Lift,d.Drop,d.ManualLod}.Any(v=>v.HasValue&&(v<0||v>11)))return false;
   if(MouseCalibrationDirty(d)&&(d.DeviceId.Length==0||!MouseZoneUiFacts.Timestamp(d.CapturedAt)))return false;
   if(d.DirtyMode&&!d.Mode.HasValue||d.DirtyPreset&&(d.Mode!=0||!d.Material.HasValue||!MouseCalibrationPresetIds.Contains(d.Material.Value))||d.DirtyGlass&&!d.Glass.HasValue)return false;
   if(d.DirtyLod&&(d.Mode!=255||!d.LodMode.HasValue||!d.NormalLod.HasValue||!d.Lift.HasValue||!d.Drop.HasValue||!d.ManualLod.HasValue||d.LodMode==1&&(d.Lift<1||d.Drop<1||d.Lift<d.Drop)||d.LodMode==2&&d.ManualLod<1))return false;return true;
  }
  MouseCalibrationObservation MouseCalibrationRead(Dictionary<string,object> state){var id=MouseZoneUiFacts.Read(state);var result=new MouseCalibrationObservation{Source=state,DeviceId=id.DeviceId??"",CapturedAt=id.CapturedAt};if(!id.IdentityConfirmed)return result;var snapshot=GearMap(state,"snapshot");if(KeyboardLightingUiFacts.Contains(state,"readCapabilities","mouseCalibrationInfo")&&KeyboardLightingUiFacts.Contains(state,"readCapabilities","mouseCalibrationLOD"))try{result.Record=new MouseCalibrationRecord(snapshot);}catch(ArgumentException){}if(KeyboardLightingUiFacts.Contains(state,"readCapabilities","mouseTrackOnGlass"))result.Glass=OriginalStateFlag(snapshot,"mouseTrackOnGlass");result.CanMode=result.Record!=null&&GearCanSet(state,"mouseCalibrationMode");result.CanPreset=result.Record!=null&&GearCanSet(state,"mouseCalibrationPreset");result.CanLod=result.Record!=null&&GearCanSet(state,"mouseCalibrationLOD");result.CanGlass=result.Glass.HasValue&&GearCanSet(state,"mouseTrackOnGlass");return result;}
  bool MouseCalibrationObservationCurrent(Dictionary<string,object> state){Dictionary<string,object> current;if(state==null||mouseCalibrationObservation==null||mouseCalibrationWorkerSession==null||!Object.ReferenceEquals(mouseCalibrationWorkerSession,gearWorker.SessionIdentity)||!gearStates.TryGetValue("mouse",out current)||!Object.ReferenceEquals(current,state)||!Object.ReferenceEquals(mouseCalibrationObservation.Source,state))return false;var read=MouseCalibrationRead(state);return read.DeviceId==mouseCalibrationObservation.DeviceId&&read.CapturedAt==mouseCalibrationObservation.CapturedAt&&read.Glass==mouseCalibrationObservation.Glass&&read.CanMode==mouseCalibrationObservation.CanMode&&read.CanPreset==mouseCalibrationObservation.CanPreset&&read.CanLod==mouseCalibrationObservation.CanLod&&read.CanGlass==mouseCalibrationObservation.CanGlass&&(read.Record==null?mouseCalibrationObservation.Record==null:read.Record.Same(mouseCalibrationObservation.Record));}
  MouseCalibrationDraft MouseCalibrationValues(Dictionary<string,object> state){var read=MouseCalibrationRead(state);if(mouseCalibrationDraft==null||mouseCalibrationDraft.DeviceId!=read.DeviceId){mouseCalibrationDraft=new MouseCalibrationDraft{DeviceId=read.DeviceId};mouseCalibrationObservation=null;mouseCalibrationWorkerSession=null;}var d=mouseCalibrationDraft;if((read.Record!=null||read.Glass.HasValue)&&!Object.ReferenceEquals(state,mouseCalibrationExcludedReference)){if(!Object.ReferenceEquals(mouseCalibrationObservation==null?null:mouseCalibrationObservation.Source,state)){mouseCalibrationObservation=read;mouseCalibrationWorkerSession=gearWorker.SessionIdentity;}d.CapturedAt=read.CapturedAt;if(!d.DirtyMode&&!d.DirtyPreset)d.Mode=read.Record==null?(int?)null:read.Record.Mode;if(!d.DirtyPreset)d.Material=read.Record==null?(int?)null:read.Record.Material;if(!d.DirtyLod){d.LodMode=read.Record==null?(int?)null:read.Record.LodMode;d.NormalLod=read.Record==null?(int?)null:read.Record.Normal;d.Lift=read.Record==null?(int?)null:read.Record.Lift;d.Drop=read.Record==null?(int?)null:read.Record.Drop;d.ManualLod=read.Record==null?(int?)null:read.Record.Manual;}if(!d.DirtyGlass)d.Glass=read.Glass;}else if(!Object.ReferenceEquals(state,mouseCalibrationExcludedReference)){if(!d.DirtyMode&&!d.DirtyPreset)d.Mode=null;if(!d.DirtyPreset)d.Material=null;if(!d.DirtyLod){d.LodMode=null;d.NormalLod=null;d.Lift=null;d.Drop=null;d.ManualLod=null;}if(!d.DirtyGlass)d.Glass=null;if(!MouseCalibrationDirty(d))d.CapturedAt=null;}return d;}
