  static List<KeyValuePair<string,object>> MouseCalibrationCommands(MouseCalibrationDraft d,MouseCalibrationRecord before){if(!MouseCalibrationDraftValid(d))throw new ArgumentException("请填写完整有效的校准草稿。抬起等级不得小于放下等级。");var commands=new List<KeyValuePair<string,object>>();if(d.DirtyPreset)commands.Add(new KeyValuePair<string,object>("mouseCalibrationPreset",d.Material.Value));else if(d.DirtyMode)commands.Add(new KeyValuePair<string,object>("mouseCalibrationMode",d.Mode.Value));if(d.DirtyLod){if(before==null||before.Mode!=255&&(!d.DirtyMode||d.Mode!=255))throw new ArgumentException("先选择自定义校准模式。");commands.Add(new KeyValuePair<string,object>("mouseCalibrationLOD",new Dictionary<string,object>{{"lodMode",d.LodMode.Value},{"normalModeLOD",d.NormalLod.Value},{"asymmetricLiftValue",d.Lift.Value},{"asymmetricDropValue",d.Drop.Value},{"manualCalibrationLOD",d.ManualLod.Value}}));}if(d.DirtyGlass)commands.Add(new KeyValuePair<string,object>("mouseTrackOnGlass",d.Glass.Value));return commands;}
